gF4(){return"\u041a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, 2 \u043a\u0433)"},
gEG(){return"\u0417\u0430\u043c\u0435\u0442\u043a\u0430"},
gMB(){return"\u0418\u043a\u043e\u043d\u043a\u0430"},
gKB(){return"\u041a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f"},
